#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_NODES 5000
#define MAX_OUTPUT 10000

typedef struct TreeNode {
    int val;
    struct TreeNode *left, *right;
} TreeNode;

static void skip_ws(const char *s, int *p) {
    while (s[*p] && isspace((unsigned char)s[*p])) (*p)++;
}

static char *next_array(const char *s, int *p) {
    skip_ws(s,p);
    if (s[*p] != '[') return NULL;
    int start=*p, depth=0;
    do {
        char c=s[(*p)++];
        if (c=='[') depth++;
        else if (c==']') depth--;
    } while (s[*p] && depth>0);
    int len=*p-start;
    char *out=(char*)malloc((size_t)len+1);
    memcpy(out,s+start,(size_t)len); out[len]='\0';
    return out;
}

static TreeNode *new_node(int v) {
    TreeNode *n=(TreeNode*)malloc(sizeof(TreeNode));
    n->val=v; n->left=NULL; n->right=NULL; return n;
}

static TreeNode *build_tree(const char *s) {
    int len=(int)strlen(s);
    if (len<=2) return NULL;
    TreeNode *queue[MAX_NODES]; int qh=0, qt=0;
    int p=1, token_index=0;
    int root_read=0;
    TreeNode *root=NULL;
    while (p<len-1) {
        while (p<len-1 && (isspace((unsigned char)s[p]) || s[p]==',')) p++;
        if (p>=len-1) break;
        int start=p;
        while (p<len-1 && s[p]!=',' && !isspace((unsigned char)s[p])) p++;
        int tlen=p-start;
        char tok[32];
        if (tlen>=31) return NULL;
        memcpy(tok,s+start,(size_t)tlen); tok[tlen]='\0';
        int isnull=(strcmp(tok,"null")==0);
        if (!root_read) {
            root_read=1;
            if (isnull) return NULL;
            root=new_node(atoi(tok));
            queue[qt++]=root;
        } else {
            if (qh>=qt) break;
            TreeNode *parent=queue[qh];
            if ((token_index&1)==0) {
                if (!isnull) { parent->left=new_node(atoi(tok)); queue[qt++]=parent->left; }
            } else {
                if (!isnull) { parent->right=new_node(atoi(tok)); queue[qt++]=parent->right; }
                qh++;
            }
            token_index++;
        }
    }
    return root;
}

static void push_left(TreeNode *node, TreeNode **stack, int *top) {
    while (node) { stack[(*top)++]=node; node=node->left; }
}

static int *getAllElements(TreeNode *root1, TreeNode *root2, int *returnSize) {
    static TreeNode *s1[MAX_NODES+1], *s2[MAX_NODES+1];
    int t1=0,t2=0;
    int *out=(int*)malloc(sizeof(int)*MAX_OUTPUT);
    int n=0;
    push_left(root1,s1,&t1); push_left(root2,s2,&t2);
    while (t1 || t2) {
        if (!t2 || (t1 && s1[t1-1]->val <= s2[t2-1]->val)) {
            TreeNode *node=s1[--t1]; out[n++]=node->val; push_left(node->right,s1,&t1);
        } else {
            TreeNode *node=s2[--t2]; out[n++]=node->val; push_left(node->right,s2,&t2);
        }
    }
    *returnSize=n; return out;
}

int main(void) {
    char line[400000];
    if (!fgets(line,sizeof(line),stdin)) return 0;
    int p=1;
    char *a=next_array(line,&p);
    while (line[p] && (line[p]==',' || isspace((unsigned char)line[p]))) p++;
    char *b=next_array(line,&p);
    TreeNode *root1=build_tree(a), *root2=build_tree(b);
    int returnSize=0;
    int *result=getAllElements(root1,root2,&returnSize);
    putchar('[');
    for(int i=0;i<returnSize;i++){ if(i) putchar(','); printf("%d",result[i]); }
    puts("]");
    free(a); free(b); free(result);
    return 0;
}

