        char c = s[pos++];
        if (c == '[') depth++;
        else if (c == ']') depth--;
    } while (pos < s.size() && depth > 0);
    return s.substr(start, pos - start);
}

TreeNode* buildTree(const string& s) {
    if (s == "[]") return nullptr;
    vector<string> tok;
    string inner = s.substr(1, s.size()-2);
    string cur;
    for (char c: inner) {
        if (c == ',') { tok.push_back(cur); cur.clear(); }
        else cur.push_back(c);
    }
    if (!cur.empty() || !inner.empty()) tok.push_back(cur);
    auto clean = [](string x) {
        size_t l=0,r=x.size();
        while(l<r && isspace((unsigned char)x[l])) l++;
        while(r>l && isspace((unsigned char)x[r-1])) r--;
        return x.substr(l,r-l);
    };
    for (auto& x: tok) x=clean(x);
    if (tok.empty() || tok[0] == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(tok[0]));
