        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }

    static String readTreeJson(String input, int[] pos) {
        while (pos[0] < input.length() && Character.isWhitespace(input.charAt(pos[0]))) pos[0]++;
        if (input.charAt(pos[0]) != '[') throw new IllegalArgumentException("Expected array");
        int start = pos[0], depth = 0;
        do {
            char c = input.charAt(pos[0]++);
            if (c == '[') depth++;
            else if (c == ']') depth--;
        } while (pos[0] < input.length() && depth > 0);
        return input.substring(start, pos[0]);
    }

    static int[] parseValues(String s) {
        s = s.trim();
        if (s.equals("[]")) return new int[0];
        String inner = s.substring(1, s.length() - 1).trim();
        if (inner.isEmpty()) return new int[0];
        String[] parts = inner.split("\\s*,\\s*");
        int[] out = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            if (parts[i].equals("null")) out[i] = Integer.MIN_VALUE;
            else out[i] = Integer.parseInt(parts[i]);
        }
        return out;
    }

    static TreeNode buildTree(String json) {
        int[] a = parseValues(json);
        if (a.length == 0 || a[0] == Integer.MIN_VALUE) return null;
        TreeNode root = new TreeNode(a[0]);
        ArrayList<TreeNode> q = new ArrayList<>();
        q.add(root);
        int head = 0, i = 1;
        while (head < q.size() && i < a.length) {
            TreeNode node = q.get(head++);
            if (i < a.length && a[i] != Integer.MIN_VALUE) {
                node.left = new TreeNode(a[i]);
                q.add(node.left);
            }
            i++;
            if (i < a.length && a[i] != Integer.MIN_VALUE) {
                node.right = new TreeNode(a[i]);
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    static List<Integer> getAllElements(TreeNode root1, TreeNode root2) {
        Deque<TreeNode> s1 = new ArrayDeque<>(), s2 = new ArrayDeque<>();
        pushLeft(root1, s1);
        pushLeft(root2, s2);
        List<Integer> ans = new ArrayList<>();
        while (!s1.isEmpty() || !s2.isEmpty()) {
            if (s2.isEmpty() || (!s1.isEmpty() && s1.peek().val <= s2.peek().val)) {
                TreeNode node = s1.pop();
                ans.add(node.val);
                pushLeft(node.right, s1);
            } else {
                TreeNode node = s2.pop();
                ans.add(node.val);
                pushLeft(node.right, s2);
            }
        }
        return ans;
    }

    static void pushLeft(TreeNode node, Deque<TreeNode> stack) {
        while (node != null) {
            stack.push(node);
            node = node.left;
        }
    }

    static String listToJson(List<Integer> list) {
